// Single-file app implementing requested functions.
  try{ window.__fabanki_booted = true; }catch(e){}

  // ============================================
  // PWA & OFFLINE SUPPORT
  // ============================================

  function isIgnorableSwNetworkUpdateError(input){
    try{
      const msg = String(
        input?.message ||
        input?.reason?.message ||
        input?.reason ||
        input ||
        ''
      ).toLowerCase();
      return (
        msg.includes('failed to update a serviceworker') ||
        msg.includes('unknown error occurred when fetching the script') ||
        (msg.includes('service-worker.js') && (msg.includes('failed to update') || msg.includes('network'))) ||
        msg.includes('the network is offline') ||
        msg.includes('networkerror')
      );
    }catch(e){ return false; }
  }

  // Install a very-early guard to suppress known benign SW update rejections when offline.
  // This runs before the generic global error UI handlers later in the file.
  window.addEventListener('unhandledrejection', (event) => {
    try{
      if(isIgnorableSwNetworkUpdateError(event)){
        if(event && typeof event.preventDefault === 'function') event.preventDefault();
        if(event && typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();
        console.info('[PWA] Early ignored SW update rejection (offline/unreachable script).');
      }
    }catch(e){}
  }, true);
  
  // Service Worker Registration
  if('serviceWorker' in navigator){
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('./service-worker.js')
        .then((registration) => {
          console.log('[PWA] Service Worker registered:', registration.scope);

          const safeUpdateRegistration = () => {
            try{
              return registration.update().catch((err) => {
                if(isIgnorableSwNetworkUpdateError(err) || !navigator.onLine){
                  console.info('[PWA] Service Worker update skipped (offline/unreachable):', err?.message || err);
                  return;
                }
                console.warn('[PWA] Service Worker update failed:', err);
              });
            }catch(err){
              if(!(isIgnorableSwNetworkUpdateError(err) || !navigator.onLine)){
                console.warn('[PWA] Service Worker update threw synchronously:', err);
              }
              return Promise.resolve();
            }
          };
          
          // Check for updates immediately on page load
          safeUpdateRegistration();
          
          // Check for updates every 5 minutes
          setInterval(() => {
            safeUpdateRegistration();
          }, 5 * 60 * 1000);
          
          // Handle updates
          registration.addEventListener('updatefound', () => {
            const newWorker = registration.installing;
            newWorker.addEventListener('statechange', () => {
              if(newWorker.state === 'installed' && navigator.serviceWorker.controller){
                // New version available - show notification
                showUpdateNotification();
              }
            });
          });
          
          // Also check if there's already a waiting worker (from a previous update check)
          if(registration.waiting){
            showUpdateNotification();
          }
        })
        .catch((error) => {
          console.error('[PWA] Service Worker registration failed:', error);
        });
      
      // Listen for messages from service worker
      navigator.serviceWorker.addEventListener('message', (event) => {
        if(event.data.type === 'QUEUE_OFFLINE_REQUEST'){
          queueOfflineAction(event.data.data);
        }
        if(event.data.type === 'SYNC_OFFLINE_REQUESTS'){
          syncOfflineQueue();
        }
      });
      
      // Handle controller change (when update is activated)
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        console.log('[PWA] Service Worker Controller changed - update activated');
        // Remove update notification when update is applied
        const notification = document.querySelector('[data-update-notification]');
        if(notification) notification.remove();
      });
    });
  }
  
  // IndexedDB for offline queue
  let offlineDB = null;

  // === SYNC BLOCKED WARNING BANNER ===
  function showSyncBlockedBanner() {
    if (document.getElementById('syncBlockedBanner')) return;
    const banner = document.createElement('div');
    banner.id = 'syncBlockedBanner';
    banner.style = 'background:#ffecb3;color:#a00;padding:10px 16px;font-weight:bold;text-align:center;position:fixed;top:0;left:0;right:0;z-index:9999;box-shadow:0 2px 8px #0002;';
    banner.innerHTML = '⚠️ Synchronisation bloquée : l\'application n\'a pas pu terminer la restauration du cloud.<br>Vos progrès ne sont enregistrés que localement.<br>' +
      '<button id="forceSyncBtn" style="margin-top:8px;padding:4px 12px;font-weight:bold;">Forcer la synchronisation</button>';
    document.body.appendChild(banner);
    document.body.style.paddingTop = '60px';
    document.getElementById('forceSyncBtn').onclick = function() {
      window.__cloudRestoreCompleted = true;
      hideSyncBlockedBanner();
      alert('Synchronisation cloud réactivée. Vos prochaines actions seront synchronisées.');
    };
  }
  function hideSyncBlockedBanner() {
    const banner = document.getElementById('syncBlockedBanner');
    if (banner) banner.remove();
    document.body.style.paddingTop = '';
  }
  // Expose for debugging
  window.__fabanki_showSyncBlockedBanner = showSyncBlockedBanner;
  window.__fabanki_hideSyncBlockedBanner = hideSyncBlockedBanner;
  
  function initOfflineDB(){
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('FabAnkiOffline', 1);
      
      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        offlineDB = request.result;
        resolve(offlineDB);
      };
      
      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        
        // Create object stores
        if(!db.objectStoreNames.contains('offlineQueue')){
          const store = db.createObjectStore('offlineQueue', { keyPath: 'id', autoIncrement: true });
          store.createIndex('timestamp', 'timestamp', { unique: false });
        }
        
        if(!db.objectStoreNames.contains('userData')){
          db.createObjectStore('userData', { keyPath: 'key' });
        }
      };
    });
  }
  
  // Queue offline actions
  async function queueOfflineAction(actionData){
    try{
      if(!offlineDB) await initOfflineDB();
      
      const transaction = offlineDB.transaction(['offlineQueue'], 'readwrite');
      const store = transaction.objectStore('offlineQueue');
      
      await store.add({
        ...actionData,
        timestamp: Date.now(),
        retries: 0
      });
      
      console.log('[Offline] Action queued:', actionData);
      updateOfflineIndicator();
    }catch(error){
      console.error('[Offline] Failed to queue action:', error);
    }
  }
  
  // Get all queued actions
  async function getQueuedActions(){
    try{
      if(!offlineDB) await initOfflineDB();
      
      return new Promise((resolve, reject) => {
        const transaction = offlineDB.transaction(['offlineQueue'], 'readonly');
        const store = transaction.objectStore('offlineQueue');
        const request = store.getAll();
        
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    }catch(error){
      console.error('[Offline] Failed to get queued actions:', error);
      return [];
    }
  }
  
  // Remove action from queue
  async function removeQueuedAction(id){
    try{
      if(!offlineDB) await initOfflineDB();
      
      const transaction = offlineDB.transaction(['offlineQueue'], 'readwrite');
      const store = transaction.objectStore('offlineQueue');
      await store.delete(id);
      
      console.log('[Offline] Action removed from queue:', id);
      updateOfflineIndicator();
    }catch(error){
      console.error('[Offline] Failed to remove action:', error);
    }
  }
  
  // Sync offline queue when online.
  // Note: Firestore SDK handles offline persistence natively.
  // This function clears any stale IndexedDB entries and is kept for legacy call sites.
  async function syncOfflineQueue(){
    if(!navigator.onLine) return;
    try{
      const actions = await getQueuedActions();
      for(const action of actions){ await removeQueuedAction(action.id); }
      updateOfflineIndicator();
      console.log('[Offline] syncOfflineQueue: cleared ' + actions.length + ' stale entries');
    }catch(e){ console.warn('[Offline] syncOfflineQueue error:', e); }
  }

  // Online/Offline event listeners
  window.addEventListener('online', () => {
    console.log('[PWA] Back online');
    updateOnlineStatus(true);
    syncOfflineQueue();
    // Trigger Firestore sync on reconnect (SDK does not auto-push pending writes via autoSync)
    setTimeout(() => {
      try{
        if(window.__cloudRestoreCompleted === true && localStorage.getItem('fabanki:mode') === 'synced'){
          if(typeof autoSync === 'function') autoSync().catch(e => console.warn('[PWA] autoSync on reconnect failed:', e));
        }
      }catch(e){}
    }, 800);
  });

  window.addEventListener('offline', () => {
    console.log('[PWA] Gone offline');
    updateOnlineStatus(false);
  });

  // Pull fresh cloud state when the user returns to this tab (cross-device sync)
  let __lastVisibilitySyncAt = 0;
  document.addEventListener('visibilitychange', () => {
    if(document.visibilityState !== 'visible') return;
    const now = Date.now();
    if(now - __lastVisibilitySyncAt < 60000) return; // max once per minute (cardStates incremental is cheap)
    __lastVisibilitySyncAt = now;
    if(localStorage.getItem('fabanki:mode') !== 'synced') return;
    if(!navigator.onLine) return;
    try{
      sessionStorage.removeItem('fabanki:sess_restore_ok');
      sessionStorage.removeItem('fabanki:fabanki_sync_meta_rev_cache');
    }catch(e){}
    if(typeof window.__fabanki_invalidateCloudCardPullCache === 'function'){
      try{ window.__fabanki_invalidateCloudCardPullCache(); }catch(e){}
    }
    if(typeof window.restoreFromCloud === 'function'){
      window.restoreFromCloud().catch(e => console.warn('[visibilitychange] restoreFromCloud failed:', e));
    }
  });

  // === SYNC BLOCKED BANNER CHECK ===
  setTimeout(function() {
    try {
      if (typeof window.__cloudRestoreCompleted !== 'undefined' && window.__cloudRestoreCompleted === false) {
        showSyncBlockedBanner();
      }
    } catch(e) {}
  }, 3500);
  // Hide banner if sync becomes unblocked
  setInterval(function() {
    try {
      if (typeof window.__cloudRestoreCompleted !== 'undefined' && window.__cloudRestoreCompleted === true) {
        hideSyncBlockedBanner();
      }
    } catch(e) {}
  }, 2000);
  
  // Initialize offline DB on load
  initOfflineDB().catch(console.error);

