  function setupTimerMode(card){
    // Load saved timer settings
    const savedSettings = localStorage.getItem(`fabanki:timer_settings:${deckKey}`);
    if(savedSettings){
      try{
        timerSettings = JSON.parse(savedSettings);
      }catch(e){}
    }
    
    // Calculate adjusted time based on card size
    let adjustedFrontTime = timerSettings.frontTime;
    let adjustedBackTime = timerSettings.backTime;
    
    // Get card content length
    if(card && card.fields){
      const fieldOrder = card._fieldOrder || Object.keys(card.fields);
      const meanCardLength = 200; // Approximate mean character count for a card
      
      if(fieldOrder.length > 0){
        const frontFieldName = fieldOrder[0];
        const frontField = card.fields[frontFieldName];
        const frontContent = typeof frontField === 'string' ? frontField : '';
        const frontLength = frontContent.replace(/<[^>]*>/g, '').length; // Remove HTML
        
        if(frontLength > 1.5 * meanCardLength){
          adjustedFrontTime = timerSettings.frontTime * 1.3; // Add 30% time
        }
      }
      
      if(fieldOrder.length > 1){
        const backFieldName = fieldOrder[1];
        const backField = card.fields[backFieldName];
        const backContent = typeof backField === 'string' ? backField : '';
        const backLength = backContent.replace(/<[^>]*>/g, '').length; // Remove HTML
        
        if(backLength > 1.5 * meanCardLength){
          adjustedBackTime = timerSettings.backTime * 1.3; // Add 30% time
        }
      }
    }

    // Favorite cards get double review time.
    const favoriteMultiplier = getCardFavoriteMultiplier(card);
    adjustedFrontTime *= favoriteMultiplier;
    adjustedBackTime *= favoriteMultiplier;
    
    // Initialize timer state
    if(!window.timerModeState){
      window.timerModeState = {
        cardStartTime: Date.now(),
        frontCardStartTime: Date.now(),
        isShowingBack: false,
        currentTimeLimit: adjustedFrontTime * 1000,
        frontTimeSeconds: adjustedFrontTime,
        backTimeSeconds: adjustedBackTime,
        autoClickActive: false,
        timeoutHandle: null,
        animationHandle: null,
        fixedButtonState: null
      };
    }else{
      window.timerModeState.cardStartTime = Date.now();
      window.timerModeState.frontCardStartTime = Date.now();
      window.timerModeState.isShowingBack = false;
      window.timerModeState.currentTimeLimit = adjustedFrontTime * 1000;
      window.timerModeState.frontTimeSeconds = adjustedFrontTime;
      window.timerModeState.backTimeSeconds = adjustedBackTime;
      window.timerModeState.fixedButtonState = null;
    }
    
    // Remove existing timer UI
    const existingTimer = document.getElementById('timerModeContainer');
    if(existingTimer) existingTimer.remove();
    
    const cardArea = document.getElementById('cardArea');
    if(!cardArea) return;
    
    // Create timer container
    const container = document.createElement('div');
    container.id = 'timerModeContainer';
    container.style.cssText = 'margin-top:16px;padding:12px;background:#f0f9ff;border-radius:8px;border:1px solid #bfdbfe;';
    
    // Timer bar
    const timerBar = document.createElement('div');
    timerBar.id = 'timerBar';
    timerBar.style.cssText = 'width:100%;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;margin-bottom:8px;';
    
    const timerFill = document.createElement('div');
    timerFill.id = 'timerFill';
    timerFill.style.cssText = 'height:100%;background:#10b981;width:0%;transition:width 0.1s linear;';
    
    timerBar.appendChild(timerFill);
    container.appendChild(timerBar);
    
    // Timer text
    const timerText = document.createElement('div');
    timerText.id = 'timerText';
    timerText.style.cssText = 'font-size:0.85em;color:#666;text-align:center;';
    timerText.textContent = `Face: ${Math.ceil(adjustedFrontTime)}s`;
    container.appendChild(timerText);
    
    cardArea.appendChild(container);
    
    // Start timer animation (only if not paused for onboarding)
    if(!window.__timerPausedForOnboarding){
      startTimerAnimation();
    }
  }
  
  function setupRushMode(card){
    // Load saved rush settings
    const savedSettings = localStorage.getItem(`fabanki:rush_settings:${deckKey}`);
    if(savedSettings){
      try{
        rushSettings = JSON.parse(savedSettings);
      }catch(e){}
    }
    
    // Initialize rush state
    if(!window.rushModeState){
      window.rushModeState = {
        goodCardsInRow: 0,
        cardStartTime: Date.now(),
        isShowingBack: false,
        currentTimeLimit: 0,
        timeoutHandle: null,
        animationHandle: null,
        timerExpired: false
      };
    }
    
    // Calculate current time limit using the formula:
    // ([number good card in a row])*[Hardest timer]+([difficulty]-[number good card in a row])*[Easiest timer]
    const goodCards = window.rushModeState.goodCardsInRow;
    const difficulty = rushSettings.difficulty;
    const hardest = rushSettings.hardestTime;
    const easiest = rushSettings.easiestTime;
    
    const frontTime = (goodCards * hardest + (difficulty - goodCards) * easiest) / difficulty;
    const adjustedFrontTime = frontTime * getCardFavoriteMultiplier(card);
    
    window.rushModeState.cardStartTime = Date.now();
    window.rushModeState.isShowingBack = false;
    window.rushModeState.currentTimeLimit = adjustedFrontTime * 1000;
    window.rushModeState.timerExpired = false;
    
    // Remove existing rush UI
    const existingRush = document.getElementById('rushModeContainer');
    if(existingRush) existingRush.remove();
    
    const cardArea = document.getElementById('cardArea');
    if(!cardArea) return;
    
    // Create rush container
    const container = document.createElement('div');
    container.id = 'rushModeContainer';
    container.style.cssText = 'margin-top:16px;padding:12px;background:#fff4e6;border-radius:8px;border:1px solid #fbbf24;';
    
    // Timer bar
    const timerBar = document.createElement('div');
    timerBar.id = 'rushTimerBar';
    timerBar.style.cssText = 'width:100%;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;margin-bottom:12px;';
    
    const timerFill = document.createElement('div');
    timerFill.id = 'rushTimerFill';
    timerFill.style.cssText = 'height:100%;background:#3b82f6;width:0%;transition:width 0.1s linear;';
    
    timerBar.appendChild(timerFill);
    container.appendChild(timerBar);
    
    // Timer text
    const timerText = document.createElement('div');
    timerText.id = 'rushTimerText';
    timerText.style.cssText = 'font-size:0.85em;color:#666;text-align:center;margin-bottom:12px;';
    timerText.textContent = `â±ï¸ Face: ${adjustedFrontTime.toFixed(1)}s`;
    container.appendChild(timerText);
    
    // Difficulty bar
    const difficultyBarContainer = document.createElement('div');
    difficultyBarContainer.style.cssText = 'margin-top:8px;';
    
    const difficultyLabel = document.createElement('div');
    difficultyLabel.style.cssText = 'font-size:0.75em;color:#666;margin-bottom:4px;text-align:center;';
    difficultyLabel.textContent = `ðŸŽ¯ ProgrÃ¨s: ${goodCards}/${difficulty}`;
    difficultyBarContainer.appendChild(difficultyLabel);
    
    const difficultyBar = document.createElement('div');
    difficultyBar.id = 'rushDifficultyBar';
    difficultyBar.style.cssText = 'width:100%;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;';
    
    const difficultyFill = document.createElement('div');
    difficultyFill.id = 'rushDifficultyFill';
    const difficultyProgress = Math.min(100, (goodCards / difficulty) * 100);
    difficultyFill.style.cssText = `height:100%;background:#10b981;width:${difficultyProgress}%;transition:width 0.3s ease;`;
    
    difficultyBar.appendChild(difficultyFill);
    difficultyBarContainer.appendChild(difficultyBar);
    container.appendChild(difficultyBarContainer);
    
    cardArea.appendChild(container);
    
    // Start timer animation
    startRushTimerAnimation();
  }
  
  function startRushTimerAnimation(){
    if(!window.rushModeState) return;
    
    const state = window.rushModeState;
    const timerFill = document.getElementById('rushTimerFill');
    const timerText = document.getElementById('rushTimerText');
    
    if(!timerFill || !timerText) return;
    
    // Clear any existing animation
    if(state.animationHandle){
      cancelAnimationFrame(state.animationHandle);
      state.animationHandle = null;
    }
    if(state.timeoutHandle){
      clearTimeout(state.timeoutHandle);
      state.timeoutHandle = null;
    }
    
    const startTime = state.cardStartTime;
    const timeLimit = state.currentTimeLimit;
    
    const updateAnimation = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(100, (elapsed / timeLimit) * 100);
      
      if(timerFill){
        timerFill.style.width = progress + '%';
      }
      
      const remaining = Math.max(0, (timeLimit - elapsed) / 1000);
      if(timerText){
        // Only show timer on front side
        if(!state.isShowingBack){
          timerText.textContent = `â±ï¸ Face: ${remaining.toFixed(1)}s`;
        } else {
          timerText.textContent = '';
        }
      }
      
      if(progress < 100 && reviewMode === 'rush'){
        state.animationHandle = requestAnimationFrame(updateAnimation);
      } else if(progress >= 100 && !state.timerExpired){
        state.timerExpired = true;
        handleRushTimerExpired();
      }
    };
    
    state.animationHandle = requestAnimationFrame(updateAnimation);
  }
  
  function handleRushTimerExpired(){
    // When timer expires, only show "RatÃ©" button - BUT ONLY IF ON FRONT SIDE
    // If on back side, do nothing (don't auto-fail)
    if(!window.rushModeState || window.rushModeState.isShowingBack) return;
    
    const respButtons = document.getElementById('respButtons');
    if(!respButtons) return;
    
    // Hide all buttons except "RatÃ©"
    const buttons = respButtons.querySelectorAll('button');
    buttons.forEach(btn => {
      const text = btn.textContent.trim();
      if(text !== 'RatÃ©' && text !== 'ðŸ”´ RatÃ©'){
        btn.style.display = 'none';
      } else {
        // Center the RatÃ© button text
        btn.style.width = '100%';
        btn.style.textAlign = 'center';
        btn.style.justifyContent = 'center';
      }
    });
    
    // Stop the timer animation
    if(window.rushModeState){
      if(window.rushModeState.animationHandle){
        cancelAnimationFrame(window.rushModeState.animationHandle);
        window.rushModeState.animationHandle = null;
      }
    }
  }
  
  function stopRushTimers(){
    if(!window.rushModeState) return;
    
    if(window.rushModeState.animationHandle){
      cancelAnimationFrame(window.rushModeState.animationHandle);
      window.rushModeState.animationHandle = null;
    }
    
    if(window.rushModeState.timeoutHandle){
      clearTimeout(window.rushModeState.timeoutHandle);
      window.rushModeState.timeoutHandle = null;
    }
  }
  
  function setupActiveMemoryMode(card){
    // Complete welcome quest: launch active memory mode (only once)
    if(typeof completeWelcomeQuestMission === 'function'){
      completeWelcomeQuestMission('part3', 'active_memory_launched', 10);
    }
    
    // Show front for 3 seconds with blue progress bar timer, then hide it until "Afficher la RÃ©ponse" is clicked
    // Skip if paused for onboarding
    if(window.__activeMemoryPausedForOnboarding) return;
    
    const frontEl = $('#front');
    if(frontEl){
      frontEl.style.display = 'flex';
      
      // Remove any existing timer container and create a fresh one for each card
      const existingContainer = document.getElementById('activeMemoryTimerContainer');
      if(existingContainer) existingContainer.remove();
      
      const timerContainer = document.createElement('div');
      timerContainer.id = 'activeMemoryTimerContainer';
      timerContainer.style.cssText = 'margin-top:12px;padding:8px;background:#f0f9ff;border-radius:8px;border:1px solid #bfdbfe;';
      
      const timerBar = document.createElement('div');
      timerBar.id = 'activeMemoryBar';
      timerBar.style.cssText = 'width:100%;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;';
      
      const fillDiv = document.createElement('div');
      fillDiv.id = 'activeMemoryFill';
      fillDiv.style.cssText = 'width:0%;height:100%;background:#3b82f6;';
      timerBar.appendChild(fillDiv);
      
      timerContainer.appendChild(timerBar);
      
      // Insert timer below the card content (find cardArea and append after it)
      const cardArea = document.getElementById('cardArea');
      if(cardArea){
        cardArea.appendChild(timerContainer);
      }
      
      const timerFill = document.getElementById('activeMemoryFill');
      const startTime = Date.now();
      const duration = 3000; // Always 3 seconds for each card
      
      // Store the timer state for this card
      window.__activeMemoryTimerState = {
        startTime: startTime,
        duration: duration,
        timerContainer: timerContainer,
        timerFill: timerFill,
        frontEl: frontEl,
        animationHandle: null,
        timeoutHandle: null
      };
      
      const updateTimer = () => {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(100, (elapsed / duration) * 100);
        if(timerFill){
          timerFill.style.width = progress + '%';
        }
        
        if(progress < 100){
          window.__activeMemoryTimerState.animationHandle = requestAnimationFrame(updateTimer);
        } else {
          if(timerContainer) timerContainer.style.display = 'none';
        }
      };
      
      window.__activeMemoryTimerState.animationHandle = requestAnimationFrame(updateTimer);
      
      // Hide front after 3 seconds
      const hideTimeout = setTimeout(() => {
        if(frontEl && reviewMode === 'activeMemory'){
          frontEl.style.display = 'none';
          frontEl.style.flex = '0 0 auto';
        }
        if(timerContainer) timerContainer.style.display = 'none';
      }, duration);
      
      window.__activeMemoryTimerState.timeoutHandle = hideTimeout;
    }
  }

  function resetHoldModeUI(){
    const backEl = $('#back');
    if(!backEl) return;
    backEl.classList.remove('hold-back', 'hold-back--revealed');
    const overlay = backEl.querySelector('.hold-blur-box');
    if(overlay) overlay.remove();
    const inner = backEl.querySelector('.hold-back__inner');
    if(inner){
      while(inner.firstChild){
        backEl.insertBefore(inner.firstChild, inner);
      }
      inner.remove();
    }
  }

  function setupHoldMode(card){
    const backEl = $('#back');
    if(!backEl || !card) return;
    const respButtons = $('#respButtons');
    const showAnswerBtn = $('#showAnswer');
    if(showAnswerBtn) showAnswerBtn.style.display = 'none';
    if(respButtons) respButtons.style.display = 'inline-flex';

    renderBack(card);
    backEl.style.display = 'block';
    backEl.style.flex = '1 1 auto';
    backEl.classList.add('hold-back');

    const inner = document.createElement('div');
    inner.className = 'hold-back__inner';
    while(backEl.firstChild){
      inner.appendChild(backEl.firstChild);
    }
    backEl.appendChild(inner);

    const overlay = document.createElement('div');
    overlay.className = 'hold-blur-box';
    overlay.textContent = 'Maintiens pour voir la reponse';
    backEl.appendChild(overlay);

    const reveal = (ev) => {
      try{
        if(ev && overlay.setPointerCapture && ev.pointerId != null){
          overlay.setPointerCapture(ev.pointerId);
        }
      }catch(e){}
      backEl.classList.add('hold-back--revealed');
    };
    const conceal = () => {
      backEl.classList.remove('hold-back--revealed');
    };

    if(window.PointerEvent){
      overlay.addEventListener('pointerdown', (ev) => { ev.preventDefault(); reveal(ev); });
      overlay.addEventListener('pointerup', conceal);
      overlay.addEventListener('pointerleave', conceal);
      overlay.addEventListener('pointercancel', conceal);
    } else {
      overlay.addEventListener('touchstart', (ev) => { ev.preventDefault(); reveal(ev); }, {passive:false});
      overlay.addEventListener('touchend', conceal);
      overlay.addEventListener('touchcancel', conceal);
      overlay.addEventListener('mousedown', (ev) => { ev.preventDefault(); reveal(ev); });
      overlay.addEventListener('mouseup', conceal);
      overlay.addEventListener('mouseleave', conceal);
    }
  }

